import {section,table,cite,topic,mountTopic} from './topic-tools.js';
import {texEq as eq,inlineMath} from './math.js';
import {traceLab,mountTrace} from './array-patterns-tools.js';
import {hhTrace,arrivals,questionBound} from './problem-solving-model.js';
export const problemSolvingMeta={slug:'math/problem-solving',title:'Mathematical Problem Solving',description:'Model hidden states, probability and guarantees before choosing counting, expectation, arrival processes, information bounds, invariants or rates.',date:'2026-08-30',updated:'2026-10-14',topicPath:['math'],tags:['brain teasers','counting','expectation','Poisson','invariants','pigeonhole','symmetry'],learningGoals:['Separate existence, probability, expectation and worst-case guarantees.','Build a sufficient state and justify a stochastic model.','Prove impossibility, termination and optimality with the correct conditions.'],related:['math/probability','math/information','algorithms/choosing'],prototype:true,visibility:'public',kind:'dense-topic'};
export const problemSolvingAliases=[];
export const problemSolvingSections=[['objective','What would count as an answer?'],['cases','Define the elementary outcomes'],['conditioning','Conditioning changes the relevant worlds'],['expectation','Count events with indicators'],['states','Keep only the useful past'],['hh-lab','Probability mass moves through suffix states'],['arrivals','A rate is not a probability'],['arrival-lab','One count event, one waiting-time event'],['streams','Combine, label and condition arrival streams'],['information','A lower bound is not a strategy'],['guarantees','Delay the event as long as possible'],['invariants','A legal move cannot repair every difference'],['termination','Strict progress needs a well-founded domain'],['symmetry','Preserve the experiment, not just the picture'],['rates','Use total time instead of every trip'],['representation','Translate statements into constraints'],['assumptions','The same observation can fit different models'],['workflow','From a conjecture to a proof'],['sources','References']];
const frames=hhTrace();
const pct=x=>x>0&&x<0.00005?'&lt;0.01%':x<1&&x>0.99995?'&gt;99.99%':(100*x).toFixed(2)+'%';
function probabilityRow(label,p){return `<div class="probability-row"><b>${label}</b><div class="probability-track"><i style="width:${p*100}%"></i></div><span class="probability-value">${pct(p)}</span></div>`;}
function hhBody(f){return `<div class="problem-states"><div><b>No useful suffix</b><span>T → here</span><span>H → suffix H</span></div><div><b>Suffix H</b><span>T → no suffix</span><span>H → finished</span></div><div><b>Finished HH</b><span>Stay finished</span></div></div><div class="probability-rows">${probabilityRow('No suffix',f.empty)}${probabilityRow('Suffix H',f.h)}${probabilityRow('Finished',f.done)}</div><p>After ${f.n} tosses, P(T &gt; ${f.n}) = ${pct(f.survival)}. Here T is the first completion time, not an individual coin outcome.</p><p>E[min(T,${f.n})] = ${f.truncated.toFixed(6)} tosses. This finite partial tail sum approaches 6; it is not the full expectation at a finite step.</p>`;}
function arrivalBody(rate,minutes,k){const f=arrivals(rate,minutes,k);return `<p>μ = ${rate} arrivals/hour × ${minutes}/60 hour = ${f.mean.toFixed(3)} arrivals.</p><div class="probability-rows problem-counts">${f.mass.map((p,i)=>probabilityRow(String(i),p)).join('')}${probabilityRow('9+',f.tail)}</div><p>P(N(t) ≥ ${k}) = P(T<sub>${k}</sub> ≤ t) = ${pct(f.cdf)}. Both expressions describe the same event.</p><p>${rate?`Expected time to arrival ${k}: ${f.expectedMinutes.toFixed(2)} minutes. That mean is not a deadline or a guaranteed waiting time.`:'Zero rate: no arrivals occur. Waiting time is infinite; an exponential distribution with a positive rate is not applicable.'}</p><p>Bars use a fixed 0–100% scale. The 9+ row groups the remaining count tail, not exactly nine arrivals. This is a model calculation, not sampled traffic.</p>`;}
function chessboard(){return `<figure class="problem-board-figure"><div class="problem-board" role="img" aria-label="Eight by eight board with opposite corners removed: 30 blue squares and 32 burgundy squares. Each adjacent-cell domino covers one of each.">${Array.from({length:64},(_,i)=>`<span class="${i===0||i===63?'board-removed':(Math.floor(i/8)+i%8)%2===0?'board-blue':'board-wine'}">${i===0||i===63?'×':''}</span>`).join('')}</div><figcaption>Two opposite corners have the same color. Remaining: 30 blue, 32 burgundy. Every domino needs one of each.</figcaption></figure>`;}
export function problemSolvingReader(link){return topic(problemSolvingMeta,problemSolvingSections,'Specify the worlds, the legal actions and the claim before calculating.',`
<p>A quantitative puzzle often needs only elementary tools. The difficult step is choosing a model that preserves the question. An average, a probability and a worst-case guarantee are different claims, even when they concern the same process.</p><p>First describe possible worlds and legal actions. Then ask what an action changes, reveals or preserves. Counting and algebra become useful only after those meanings are clear.</p>
${section('objective','What would count as an answer?',`${table('Match the wording to its proof obligation',['Question','Needed evidence'],[['Is it possible?','One valid construction'],['Must it happen?','A proof covering every allowed case'],['With what probability?','A specified random experiment and event'],['On average?','An expectation under that model'],['Can we guarantee it?','A strategy against the worst allowed case'],['What is the minimum?','An impossibility bound and a matching construction']])}<p>A randomized strategy can have a small mean cost and an unbounded worst case. A strategy using k steps proves an upper bound, not optimality. An information limit proves a lower bound, not an attainable procedure.</p><p>Write down replacement policy, independence, available observations, legal queries and what the answer must identify. A counterfeit coin's identity and its heavy/light status may be different requested outputs.</p>`)}
${section('cases','Define the elementary outcomes',`<p>Counting requires a definition of distinct outcomes. Choosing three people for a committee ignores order. Choosing a chair, secretary and treasurer preserves order. Drawing with replacement permits repeated choices; drawing without replacement does not.</p>${table('Counts for n distinct options and 0≤k≤n where needed',['Construction','Count'],[['Choose k without order',inlineMath(String.raw`\binom nk=\frac{n!}{k!(n-k)!}`)],['Choose and order k without repetition',inlineMath(String.raw`\frac{n!}{(n-k)!}`)],['Order all n','n!'],['Length-k sequence with repetition','nᵏ']])}<p>The product rule multiplies stage counts when every preceding construction has the stated number of continuations. If the next count depends on the first choice, sum the counts of those branches instead.</p>${eq("P(A)=\\frac{|A|}{|\\Omega|}","A is a subset of a finite nonempty sample space Ω. Every elementary outcome must have the same probability; counting category labels does not give them equal weights.")}<p>Two fair-coin tosses have four equally likely sequences: HH, HT, TH, TT. Grouping them into “two heads”, “one head” and “zero heads” does not make those three categories equally likely. Their probabilities are 1/4, 1/2 and 1/4.</p>`)}
${section('conditioning','Conditioning changes the relevant worlds',`${eq("\\begin{aligned}P(A^{\\mathrm c})&=1-P(A)\\\\P(A\\cup B)&=P(A)+P(B)-P(A\\cap B)\\\\P(A\\cap B)&=P(A)P(B\\mid A)\\end{aligned}","The complement is relative to the sample space. The last expression requires P(A) > 0 to define P(B | A). None of these rules assumes independence.")}<p>For ten independent fair-die rolls, at least one six is easier through its complement: ${inlineMath(String.raw`1-\left(\frac56\right)^{10}`)}. Multiplication is valid because the rolls are independent. Events occurring at different times are not automatically independent.</p><p>For ${inlineMath(String.raw`P(B)>0`)}, ${inlineMath(String.raw`P(A\mid B)=\frac{P(A\cap B)}{P(B)}`)}. Keep only worlds compatible with B and renormalize their weights. If a message was produced by a selection procedure, include that procedure; the message's wording alone may not specify its likelihood.</p>${eq("\\begin{aligned}P(A)&=\\sum_i P(A\\mid B_i)P(B_i)\\\\P(B_i\\mid A)&=\\frac{P(A\\mid B_i)P(B_i)}{P(A)}\\end{aligned}","The finite or countable cases Bi are disjoint and exhaustive. Use positive-probability cases for the conditional terms; zero-probability cases contribute zero. Bayes' formula requires P(A) > 0.")}<p>A table of hidden types, prior probabilities and observation likelihoods helps with tests, boxes, doors and family-information puzzles. <a href="${link('math/probability')}">Probability and Distributions →</a> gives the full conditional/joint framework.</p><p>For independent events with P(A) &gt; 0, P(B | A) equals P(B), so the intersection probability is P(A)P(B). For mutually exclusive events, the union rule reduces to P(A)+P(B).</p><p>Mutually exclusive events have zero overlap. Independent events have product overlap. Positive-probability mutually exclusive events therefore cannot also be independent.</p>`)}
${section('expectation','Count events with indicators',`<p>For a discrete quantity X with a finite expectation, ${inlineMath(String.raw`\mathbb E[X]=\sum_x xP(X=x)`)}. Instead of finding its complete distribution, sometimes write X as a sum of indicators. Indicator Iᵢ is 1 when event i occurs and 0 otherwise, so ${inlineMath(String.raw`\mathbb E[I_i]=P(\text{event }i)`)}.</p>${eq("\\mathbb E\\!\\left[\\sum_{i=1}^n I_i\\right]=\\sum_{i=1}^n\\mathbb E[I_i]=\\sum_{i=1}^nP(I_i=1)","For a finite number n of indicator variables. Independence is not required. When n = 0, both sums are zero.")}<p>In a uniformly random permutation of n≥1 objects, let Iᵢ indicate that object i stays in its original position. Each has probability 1/n, so the expected number of fixed points is ${inlineMath(String.raw`n\cdot\frac1n=1`)}.</p><p>Linearity also applies to any finite sum of random variables with finite absolute expectations: the expectation of the sum equals the sum of their expectations. Indicators are a useful special case, not a separate independence assumption.</p><p>The events are dependent. For two objects, either both remain or neither remains. Dependence does not invalidate linearity. The empty permutation has zero fixed points; the ${inlineMath(String.raw`\frac1n`)} argument does not cover n=0.</p><p>An expectation is not a typical outcome or a guarantee. If signed quantities have divergent positive and negative parts, an expression such as ∞−∞ does not define an expectation. Infinite sums require additional convergence or nonnegativity conditions.</p>`)}
${section('states','Keep only the useful past',`<p>For a waiting-time problem, store enough history to predict the next transition, but no irrelevant history. To wait for HH in independent fair tosses, the useful suffix is either empty or H. Once HH appears, the process has finished.</p>${eq("\\begin{aligned}E_0&=1+\\frac12E_1+\\frac12E_0\\\\E_1&=1+\\frac12\\,0+\\frac12E_0\\\\E_0&=6,\\qquad E_1=4\\end{aligned}","Independent fair tosses, stopping at the first consecutive HH. Each next toss costs one. E0 and E1 are finite expected remaining tosses from no useful suffix and suffix H; the finished state's expectation is zero.")}<p>From the empty state, H leaves suffix H and T leaves no useful suffix. From H, another H finishes, while T resets. The reset term is why “two heads means four tosses on average” is not the correct calculation for consecutive heads.</p><p>The equations have a finite solution here. One independent two-toss block succeeds with probability 1/4, giving a finite upper bound of eight tosses by checking only disjoint blocks. Allowing overlapping successes can only finish earlier. This supports using finite first-step expectations.</p><p>For a nonnegative integer completion time T and nonnegative integer cutoff m, ${inlineMath(String.raw`\mathbb E[\min(T,m)]=\sum_{j=0}^{m-1}P(T>j)`)}. Each included toss contributes one exactly when completion has not yet occurred. The finite sum measures truncated waiting, not a guaranteed completion by m.</p><p>A state must be sufficient for the actual model. A biased or dependent coin changes the transition probabilities, and a longer target can require more suffix states. This is stochastic state reasoning, related to <a href="${link('algorithms/dp')}">Dynamic Programming →</a>, not enumeration of every past sequence.</p>`)}
${traceLab('hh-lab','Probability mass moves through suffix states','Exact distribution over independent fair-coin sequences, not one random animation. Finished mass stays finished as toss count increases.',frames,6,hhBody,'Rows show probability mass. Every state is labeled; bar width is measured on the same probability scale.')}
${section('arrivals','A rate is not a probability',`<p>A homogeneous Poisson process has stationary independent increments and a constant rate λ&gt;0. In a short interval Δ, one arrival has probability λΔ+o(Δ), and multiple arrivals have probability o(Δ). A constant long-run average alone does not establish these properties.</p>${eq("\\begin{aligned}\\mu&=\\lambda t,\\qquad N(t)\\sim\\operatorname{Poisson}(\\mu)\\\\P(N(t)=j)&=\\frac{e^{-\\mu}\\mu^j}{j!}\\\\\\mathbb E[N(t)]&=\\operatorname{Var}(N(t))=\\mu\\end{aligned}","A homogeneous Poisson process has rate λ > 0 and interval t ≥ 0 in matching time units. The count j is a nonnegative integer. At μ = 0 the count is zero almost surely; use the PMF convention 0^0 = 1 at j = 0.")}<p>Six calls per hour during ten minutes gives ${inlineMath(String.raw`\mu=6\cdot\frac{10}{60}=1`)}. Therefore ${inlineMath(String.raw`P(\text{at least one call})=1-e^{-1}`)}, about 63.21%. The number six is a rate, not a probability of a call.</p>${eq("\\begin{aligned}P(T_1>t)&=P(N(t)=0)=e^{-\\lambda t}\\\\f_{T_1}(t)&=\\lambda e^{-\\lambda t},\\qquad t\\ge0\\\\\\mathbb E[T_1]&=\\frac1\\lambda,\\qquad\\operatorname{Var}(T_1)=\\frac1{\\lambda^2}\\end{aligned}","T1 is the wait from the start until the first arrival, with positive rate λ. Its density is zero for t < 0. Mean has time units; variance has squared-time units. The rate-zero lab boundary is not this exponential distribution.")}<p>The wait Tₖ to the kth arrival is Gamma with shape k and rate λ, also called Erlang for integer k. ${inlineMath(String.raw`\mathbb E[T_k]=\frac{k}{\lambda}`)} and ${inlineMath(String.raw`P(T_k\le t)=P(N(t)\ge k)`)}. Counts and waiting times describe the same arrivals from different directions.</p><p>Exponential memorylessness gives ${inlineMath(String.raw`P(T_1>s+t\mid T_1>s)=P(T_1>t)`)}, for nonnegative s and t. Waiting without an arrival does not make one due. This conclusion is not appropriate for scheduled buses, aging hardware or history-dependent rates. ${cite('https://www.probabilitycourse.com/chapter11/11_1_2_basic_concepts_of_the_poisson_process.php','Poisson definition and waiting-time derivation')}</p><p>The mean wait is not the median, which is ${inlineMath(String.raw`\frac{\ln2}{\lambda}`)}, or a deadline. Bursts, resource limits and self-exciting arrivals require a different model. The lab includes zero rate as a no-arrival boundary case, not an exponential distribution with rate zero.</p>`)}
<div id="arrival-lab" class="topic-scene" data-arrival-lab><h3>One count event, one waiting-time event</h3><p>Keep the homogeneous independent-increment assumptions fixed. Change rate, interval length and the arrival number.</p><label>Rate, arrivals/hour <output data-rate>6</output><input aria-label="Arrival rate" type="range" min="0" max="12" value="6"></label><label>Interval, minutes <output data-minutes>10</output><input aria-label="Arrival interval" type="range" min="0" max="60" value="10"></label><label>Arrival number <select aria-label="Arrival number"><option>1</option><option>2</option><option>3</option><option>4</option></select></label><div data-arrival-body>${arrivalBody(6,10,1)}</div></div>
${section('streams','Combine, label and condition arrival streams',`<p>Independent Poisson streams with rates λᵢ combine into a Poisson stream with rate Σᵢλᵢ. For two positive-rate streams, the next arrival's type is 1 with probability λ₁/(λ₁+λ₂), and the waiting time is exponential with their combined rate.</p><p>Independent labeling of each event as retained with probability p gives retained rate pλ and discarded rate (1−p)λ. The two labeled streams are independent before conditioning on a total. Keeping every second event is not independent labeling and does not have this thinning guarantee. ${cite('https://www.probabilitycourse.com/chapter11/11_1_3_merging_and_splitting_poisson_processes.php','Merging and independent thinning')}</p><p>Given N(t)=n for t&gt;0, the unordered event locations have the distribution of n independent uniform points in the interval. The ordered arrival times are their order statistics, not mutually independent ordered values.</p>${eq("\\begin{aligned}N(s)\\mid N(t)=n&\\sim\\operatorname{Binomial}\\!\\left(n,\\frac{s}{t}\\right)\\\\P(N(s)=j\\mid N(t)=n)&=\\binom{n}{j}\\left(\\frac{s}{t}\\right)^j\\left(1-\\frac{s}{t}\\right)^{n-j}\\end{aligned}","For rate λ > 0, t > 0, 0 ≤ s ≤ t, integer n ≥ 0 and 0 ≤ j ≤ n. Conditioning fixes the total. The endpoint cases are degenerate binomials; use 0^0 = 1 where required. Probability is zero outside the integer j range.")}<p>For four arrivals in an hour, the number in its first quarter has mean ${inlineMath(String.raw`4\cdot\frac14=1`)}. Its complement count is four minus that number. The two counts are no longer independent once their total is fixed. ${cite('https://www.biostat.umn.edu/~baolin/teaching/probmods/ipm_poisson.html','Conditional arrival locations, Lecture 4')}</p>`)}
${section('information','A lower bound is not a strategy',`${eq("b^k\\ge N\\quad\\Longrightarrow\\quad k\\ge\\left\\lceil\\frac{\\log N}{\\log b}\\right\\rceil","N ≥ 1 distinct requested answers, integer branching bound b ≥ 2 and integer worst-case depth k ≥ 0. This leaf-capacity condition is necessary, not a construction of legal queries.")}<p>A depth-k adaptive decision tree has at most b<sup>k</sup> leaves. If every hidden world must be identified separately, there must be at least N leaves. Yes/no questions have at most two branches; a balance scale has at most three.</p><p>Eight hidden cases need at least ${questionBound(8,2).depth} binary answers. Arbitrary subset questions can attain this bound by successively halving the cases. A scale cannot necessarily realize every desired partition: legal weighings restrict which cases produce each outcome.</p><p>If the answer must identify both one of n suspect coins and its heavy/light status, there are 2n worlds. If only a coarser answer is required, worlds that can safely share that answer need not occupy separate leaves. State the identification objective before counting.</p><p>Impossible branches, unequal splits and legal-query restrictions can make the bound unattainable. Adaptive strategies choose the next query from previous outcomes; non-adaptive strategies fix every query beforehand. Prove both the lower bound and a legal matching construction before claiming an optimum.</p><p><a href="${link('math/information')}">Information Theory →</a> connects probabilities to average code lengths. A worst-case leaf-count bound is not the same as an expected-length entropy bound.</p>`)}
${section('guarantees','Delay the event as long as possible',`<p>The pigeonhole principle guarantees a repeated box when more objects than boxes are assigned. More generally, N objects in n&gt;0 boxes force at least one box to contain ⌈N/n⌉ objects.</p><p>With twelve birth months, thirteen people force a shared month. Twelve people do not: put one in each month. This arrangement supplies the matching lower-bound example, not merely an intuitive argument.</p><p>For a guarantee of at least an integer r≥1 objects in one of n boxes, the delaying arrangement puts r−1 in every box. Thus n(r−1)+1 objects suffice and n(r−1) need not suffice, assuming those assignments are all allowed. Unequal capacity or prohibited assignments change the argument.</p><p>No probability model is needed. A birthday probability question with random birthdays is a different calculation; worst-case assignment is not replaced by an average distribution.</p>`)}
${section('invariants','A legal move cannot repair every difference',`<p>An invariant is a property preserved by every legal move. Candidate properties include parity, a sum or difference, a residue modulo m, permutation parity or a connectivity feature. Prove preservation for the actual move; do not assume a component count stays fixed when moves can connect components.</p><p>Remove opposite corners of an 8×8 chessboard. Both have the same color, leaving 30 of that color and 32 of the other. Every domino covering adjacent squares uses exactly one of each color. Therefore 31 dominoes cannot cover the remaining board.</p>${chessboard()}<p>Equivalently, every placed domino changes the uncovered color counts by (−1,−1), preserving their difference of two. A fully covered board would have difference zero, so it is unreachable.</p><p>Equal color counts would only remove this obstruction. They would not prove a tiling exists: disconnected regions or other shape restrictions can still prevent one. An invariant usually proves impossibility before it provides a construction.</p>`)}
${section('termination','Strict progress needs a well-founded domain',`<p>A monovariant changes strictly in one direction on each move. To prove termination, the possible values must forbid an infinite chain in that direction. A decreasing nonnegative integer works because each move lowers it by at least one.</p>${eq("\\begin{aligned}M_{t+1}&<M_t,\\qquad M_t\\in\\mathbb Z_{\\ge0}\\\\M_L&\\le M_0-L\\\\0\\le L&\\le M_0\\end{aligned}","Every legal step strictly decreases a nonnegative integer. After L steps the value has fallen by at least L, so at most M0 such steps are possible. A lower-bounded real-valued decrease alone does not give this result.")}<p>Strict decrease and a real lower bound alone are insufficient. ${inlineMath(String.raw`M_t=\frac1{t+1}`)} decreases forever while staying above zero. A real-valued potential needs an additional argument, such as a uniform decrease of at least ε&gt;0 or a finite set of allowed values.</p><p>Separate termination from efficiency. A potential can prove that a process ends without giving a useful bound in the input size. Also verify strict progress for every legal step, including ties and no-op moves.</p>`)}
${section('symmetry','Preserve the experiment, not just the picture',`<p>A transformation can equate case probabilities only when it preserves the random experiment and exchanges those cases. Relabeling a fair die's faces preserves its procedure. A weighted die can have the same shape without preserving the probability law.</p><p>Rotate, reflect, permute or relabel to simplify cases. Check exceptional configurations: some have fewer distinct images under the transformation. For two fair tosses, swapping toss positions exchanges HT and TH but leaves HH unchanged. Counting symmetry classes as equally likely would reproduce the wrong three-category model.</p><p>A bijection proves equal counts when it pairs valid objects. Probability equality additionally requires preserving their weights. Symmetry is a proof tool, not a substitute for defining the experiment.</p>`)}
${section('rates','Use total time instead of every trip',`<p>Two objects moving directly toward each other at constant speeds v₁ and v₂ close a separation D at rate v₁+v₂. The collision time is ${inlineMath(String.raw`t=\frac{D}{v_1+v_2}`)}, for positive total closing speed.</p><p>A fly traveling continuously at speed v<sub>f</sub> until the collision covers v<sub>f</sub>t. Summing every back-and-forth trip adds complexity without changing the total available flight time. This uses instantaneous turning and no pauses as idealized assumptions.</p>${eq("\\begin{aligned}r_i&=\\frac1{T_i},\\qquad i=1,\\ldots,n\\\\r_{\\mathrm{total}}&=\\sum_{i=1}^n r_i\\\\T_{\\mathrm{together}}&=\\frac1{r_{\\mathrm{total}}}\\end{aligned}","For n ≥ 1 workers, each completing one unit in positive time Ti at a constant rate. Work is perfectly divisible, rates add without interference and every worker operates throughout. Rate units are work/time; completion time is time per one unit.")}<p>Machines taking two and three hours per unit have combined rate ${inlineMath(String.raw`\frac12+\frac13=\frac56`)} units/hour. They complete one unit in ${inlineMath(String.raw`\frac65`)} hours, not the average of their completion times.</p><p>Sequential dependencies, indivisible tasks, interference and varying speed can invalidate rate addition. Track units: distance=speed×time and work=rate×time. Matching units is necessary but does not by itself establish the physical model.</p>`)}
${section('representation','Translate statements into constraints',`<p>Name unknowns before manipulating numbers. If a father and child have current ages x and y, their ages d years ago are x−d and y−d. Shift both ages by the same duration; their difference stays x−y.</p><p>Choose a representation that makes actions explicit: a table for hidden cases, a graph for routes, a state tuple for containers, a decision tree for adaptive observations, equations for conserved quantities.</p><p>When the goal is highly constrained, work backward through possible predecessor states. Every reversed step must correspond to a legal forward move. Directed transitions are not automatically reversible; a backward search may need incoming edges rather than the ordinary forward rule.</p><p><a href="${link('algorithms/choosing')}">Choosing Algorithms →</a> connects representation, requested output and maintained state. The representation should simplify the legal operations without losing information needed by the question.</p>`)}
${section('assumptions','The same observation can fit different models',`<p>Suppose the probability of seeing at least one truck in one hour is 0.99. That number alone does not determine the half-hour probability.</p><p>If the two half-hours have identical independent no-arrival probabilities q, then ${inlineMath(String.raw`q^2=0.01`)}. Therefore q=0.1 and the half-hour arrival probability is 0.9. A homogeneous Poisson model supplies these assumptions, but the single observation does not prove that model.</p>${table('Distinct models with the same one-hour probability',['Model','One-hour arrival probability','Half-hour arrival probability'],[['Independent identical halves','0.99','0.90 in either half'],['With probability 0.99, a truck in each half; otherwise none','0.99','0.99 in either half'],['With probability 0.99, only the first half has a truck','0.99','0.99 first half; 0 second half']])}<p>The second model has identical halves but dependence. The third loses stationarity. These constructions show exactly which additional assumptions the square-root answer uses.</p><p>Recognizing underdetermination is a valid result. State the extra assumption needed for a unique answer instead of silently solving a stronger question.</p>`)}
${section('workflow','From a conjecture to a proof',`<p>Use small cases n=1,2,3,4 to find a candidate pattern or counterexample. Then seek induction, a recurrence, an invariant, a bijection or a counting argument. Small successes suggest a theorem; they do not prove it.</p><p>Check empty sets, probabilities zero/one, equal values, attained boundaries and singleton states. For a minimum, pair an impossibility argument with a matching legal strategy. For an expectation, verify finiteness or state that it diverges.</p><ol><li>Write the objective and hidden states.</li><li>Specify the random model and legal observations.</li><li>List assumptions: independence, replacement, constant rates, information and movement rules.</li><li>Choose a representation and a preserved or changing quantity.</li><li>Try small cases or legal backward steps.</li><li>Derive the result, then check probability bounds, units and edge cases.</li><li>Separate a bound, a construction and an optimality proof.</li></ol><p>For revisiting these tools, a useful order is conditioning/counting, then indicators and state equations, then arrivals, guarantees, information bounds and invariants. Rates and algebra are often simpler than a long simulation.</p><p>Common failure modes are multiplying without independence, counting without equal weights, confusing means with guarantees, claiming a lower bound is attainable, using visual symmetry as probability evidence and assuming bounded real progress must terminate.</p>`)}
${section('sources','References',`<p>${cite('https://www.probabilitycourse.com/chapter11/11_1_2_basic_concepts_of_the_poisson_process.php','Poisson counts and arrival times')} · ${cite('https://www.probabilitycourse.com/chapter11/11_1_3_merging_and_splitting_poisson_processes.php','Independent stream operations')} · ${cite('https://www.biostat.umn.edu/~baolin/teaching/probmods/ipm_poisson.html','Conditional arrival locations')}</p><p><a href="${link('algorithms/backtracking')}">Backtracking →</a> makes legal branch exploration and restoration explicit. <a href="${link('algorithms/numbers')}">Bits, Numbers, and Geometry →</a> applies arithmetic and coordinate invariants to algorithms.</p><p>Interactive probabilities are calculated from explicitly stated idealized models. They are not measured arrival data or claims about a particular physical system.</p>`)}
`);}
problemSolvingMeta.searchText=problemSolvingReader(()=> '').replace(/<[^>]*>/g,' ');
export function mountProblemSolving(scope=document){mountTopic(scope,problemSolvingMeta.slug,article=>{mountTrace(article,'hh-lab',frames,hhBody);const lab=article.querySelector('[data-arrival-lab]'),rate=lab.querySelector('[aria-label="Arrival rate"]'),minutes=lab.querySelector('[aria-label="Arrival interval"]'),k=lab.querySelector('select');const draw=()=>{lab.querySelector('[data-rate]').textContent=rate.value;lab.querySelector('[data-minutes]').textContent=minutes.value;lab.querySelector('[data-arrival-body]').innerHTML=arrivalBody(Number(rate.value),Number(minutes.value),Number(k.value));};rate.addEventListener('input',draw);minutes.addEventListener('input',draw);k.addEventListener('change',draw);});}
